require_once __DIR__.'/panel_common.php';require_once __DIR__.'/toribot_api.php';
foreach(explode(';',file_get_contents(__DIR__.'/../toribot_schema.sql')) as $sql)if(trim($sql)!=='')$conn->query($sql);
if($_SERVER['REQUEST_METHOD']==='POST'){
 $data=panelInput();$action=$data['action']??'';
 if($action==='read')toriReply($conn);
 if($action==='search'){$query=trim(mb_substr((string)($data['query']??''),0,80));$id=ctype_digit($query)?(int)$query:-1;$page=max(1,min(10000,(int)($data['page']??1)));$q=$conn->prepare('SELECT COUNT(*) n FROM item_template WHERE TYPE NOT IN (9,10,34) AND id NOT IN (517,518) AND (id=? OR INSTR(LOWER(NAME),LOWER(?))>0)');$q->bind_param('is',$id,$query);$q->execute();$total=(int)$q->get_result()->fetch_assoc()['n'];$pages=max(1,(int)ceil($total/24));$page=min($page,$pages);$offset=($page-1)*24;$q=$conn->prepare('SELECT id,NAME AS name,icon_id FROM item_template WHERE TYPE NOT IN (9,10,34) AND id NOT IN (517,518) AND (id=? OR INSTR(LOWER(NAME),LOWER(?))>0) ORDER BY (id=?) DESC,id LIMIT 24 OFFSET ?');$q->bind_param('isii',$id,$query,$id,$offset);$q->execute();panelReply(['items'=>$q->get_result()->fetch_all(MYSQLI_ASSOC),'page'=>$page,'pages'=>$pages,'total'=>$total]);}
 if(!in_array($action,['save','undo'],true))panelReply(['error'=>'Thao tác không hợp lệ.'],422);
 try{
  $expected=toriInt($data['revision']??null,1,2147483647);$next=$action==='save'?toriValidate($conn,$data['config']??null):null;
  $conn->begin_transaction();$current=$conn->query('SELECT config,revision FROM tori_vip_config WHERE id=1 FOR UPDATE')->fetch_assoc();if((int)$current['revision']!==$expected){$conn->rollback();panelReply(['error'=>'Cấu hình đã thay đổi. Tải lại trước khi lưu.'],409);}
  if($action==='undo'){$id=toriInt($data['id']??null,1,2147483647);$q=$conn->prepare('SELECT before_config,revision FROM tori_vip_audit WHERE id=?');$q->bind_param('i',$id);$q->execute();$audit=$q->get_result()->fetch_assoc();if(!$audit||(int)$audit['revision']!==$expected)throw new InvalidArgumentException('Chỉ hoàn tác được thay đổi gần nhất.');$next=toriValidate($conn,json_decode($audit['before_config'],true));}
  $json=json_encode($next,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$revision=$expected+1;$admin=(int)$panelAdmin['id'];$q=$conn->prepare('INSERT INTO tori_vip_audit(admin_id,before_config,after_config,revision) VALUES(?,?,?,?)');$q->bind_param('issi',$admin,$current['config'],$json,$revision);$q->execute();$q=$conn->prepare('UPDATE tori_vip_config SET config=?,revision=? WHERE id=1');$q->bind_param('si',$json,$revision);$q->execute();$conn->commit();toriReply($conn);
 }catch(InvalidArgumentException $e){$conn->rollback();panelReply(['error'=>$e->getMessage()],422);}catch(Throwable $e){$conn->rollback();panelReply(['error'=>'Không lưu được. Cấu hình cũ được giữ nguyên.'],500);}
}
